<?php
require_once 'includes/db.php'; require_once 'includes/functions.php'; require_admin(); require_once 'includes/entities.php';
$key=$_GET['entity']??'students'; if(!isset($entities[$key])){http_response_code(404);exit('Unknown record type.');} $cfg=$entities[$key]; $table=$cfg['table']; $pk=$cfg['pk']; $fields=$cfg['fields']; $action=$_GET['action']??'list'; $id=isset($_GET['id'])?(int)$_GET['id']:0; $errors=[]; $record=[];
if($action==='delete' && $_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$stmt=$conn->prepare("DELETE FROM `$table` WHERE `$pk`=?");$stmt->bind_param('i',$id);try{$stmt->execute();flash($cfg['title'].' record deleted.');}catch(Throwable $e){flash('Cannot delete this record because related records may depend on it. Remove or update related records first.','error');}header('Location: records.php?entity='.urlencode($key));exit;}
if($action==='edit' && $id){$stmt=$conn->prepare("SELECT * FROM `$table` WHERE `$pk`=?");$stmt->bind_param('i',$id);$stmt->execute();$record=$stmt->get_result()->fetch_assoc()??[];if(!$record){flash('Record not found.','error');header('Location: records.php?entity='.urlencode($key));exit;}}
if(($action==='create'||$action==='edit') && $_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $data=[];
 foreach($fields as $name=>$f){if(!empty($f['pkinput']) && $action==='edit')continue; $val=trim((string)($_POST[$name]??'')); if($val==='' && empty($f['required'])){$data[$name]=null;continue;} if($val==='' && !empty($f['required'])){$errors[]=$f['label'].' is required.';continue;}
  if($f['type']==='email'&&!valid_email($val))$errors[]=$f['label'].' must be a valid email address.';
  if($f['type']==='tel'&&!valid_phone($val))$errors[]=$f['label'].' must be a valid phone number.';
  if(isset($f['pattern'])&&!preg_match('~'.$f['pattern'].'~u',$val))$errors[]=$f['label'].' has an invalid format.';
  if($f['type']==='number' && filter_var($val,FILTER_VALIDATE_INT)===false)$errors[]=$f['label'].' must be a whole number.';
  if($f['type']==='number'&&isset($f['min'])&&(int)$val<$f['min'])$errors[]=$f['label'].' must be at least '.$f['min'].'.';
  if($f['type']==='select'&&!array_key_exists($val,$f['options']))$errors[]='Select a valid option for '.$f['label'].'.';
  if($f['type']==='fk'&&filter_var($val,FILTER_VALIDATE_INT)===false)$errors[]='Select a valid '.$f['label'].'.';
  if($f['type']==='date'&&$val!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$val))$errors[]=$f['label'].' must be a valid date.';
  $data[$name]=$val;
 }
 if(isset($data['email'])){ $email=$data['email'];$stmt=$conn->prepare("SELECT `$pk` FROM `$table` WHERE email=? AND `$pk`<>? LIMIT 1");$exclude=$action==='edit'?$id:0;$stmt->bind_param('si',$email,$exclude);$stmt->execute();if($stmt->get_result()->num_rows)$errors[]='That email address is already in use.'; }
 if(!$errors){try{
  if($action==='edit'){$sets=[];$vals=[];$types='';foreach($data as $col=>$val){$sets[]="`$col`=?";$vals[]=$val;$types.=is_int($val)?'i':'s';}$types.='i';$vals[]=$id;$stmt=$conn->prepare("UPDATE `$table` SET ".implode(',',$sets)." WHERE `$pk`=?");$stmt->bind_param($types,...$vals);$stmt->execute();flash($cfg['title'].' record updated successfully.');}
  else{$cols=array_keys($data);if($key==='lecturers'||$key==='enrollment'){$cols=array_merge([$pk],$cols);$data=[$pk=>(int)($_POST[$pk]??0)]+$data;if((int)$data[$pk]<=0)throw new RuntimeException('Enter a positive numeric ID.');}$quoted=implode(',',array_map(fn($c)=>"`$c`",$cols));$marks=implode(',',array_fill(0,count($cols),'?'));$vals=array_values($data);$types='';foreach($vals as $v)$types.=is_int($v)?'i':'s';$stmt=$conn->prepare("INSERT INTO `$table` ($quoted) VALUES ($marks)");$stmt->bind_param($types,...$vals);$stmt->execute();flash($cfg['title'].' record created successfully.');}
  header('Location: records.php?entity='.urlencode($key));exit;
 }catch(Throwable $e){$errors[]=(str_contains(strtolower($e->getMessage()),'duplicate')?'A record with one of these unique values already exists.':'Unable to save the record. Check required related records and database constraints.');}}
 $record=array_merge($record,$_POST);
}
$pageTitle=$cfg['title'];require 'includes/header.php';
?>
<div class="page-heading"><div><h1><?= e($cfg['title']) ?></h1><p class="subheading">Create, view, update, delete and search <?= e(strtolower($cfg['title'])) ?> records.</p></div><a class="btn secondary" href="index.php">← Dashboard</a></div>
<?php if($action==='create'||$action==='edit'): ?><div class="card"><h2><?= $action==='edit'?'Edit':'Add new' ?> <?= e(rtrim($cfg['title'],'s')) ?></h2><?php if($errors): ?><div class="alert error"><ul><?php foreach($errors as $err): ?><li><?= e($err) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" action="records.php?entity=<?= e($key) ?>&action=<?= e($action) ?><?= $action==='edit'?'&id='.$id:'' ?>" novalidate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-grid">
<?php foreach($fields as $name=>$f): if(!empty($f['pkinput'])&&$action==='edit')continue; $value=$record[$name]??''; ?><div class="field"><label for="<?= e($name) ?>"><?= e($f['label']) ?><?= !empty($f['required'])?' *':'' ?></label>
<?php if($f['type']==='fk'){$opts=$conn->query('SELECT `'.$f['refpk'].'` AS id, `'.$f['display'].'` AS label FROM `'.$f['ref'].'` ORDER BY `'.$f['display'].'`'); ?><select id="<?= e($name) ?>" name="<?= e($name) ?>" <?= !empty($f['required'])?'required':'' ?>><option value="">Choose <?= e(strtolower($f['label'])) ?></option><?php while($o=$opts->fetch_assoc()): ?><option value="<?= (int)$o['id'] ?>" <?= (string)$value===(string)$o['id']?'selected':'' ?>><?= e($o['label']) ?></option><?php endwhile; ?></select>
<?php }elseif($f['type']==='select'){ ?><select id="<?= e($name) ?>" name="<?= e($name) ?>" <?= !empty($f['required'])?'required':'' ?>><option value="">Choose option</option><?php foreach($f['options'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= (string)$value===(string)$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select>
<?php }else{ ?><input id="<?= e($name) ?>" name="<?= e($name) ?>" type="<?= e($f['type']) ?>" value="<?= e($value) ?>" <?= !empty($f['required'])?'required':'' ?> <?= isset($f['pattern'])?'pattern="'.e($f['pattern']).'"':'' ?> <?= isset($f['min'])?'min="'.(int)$f['min'].'"':'' ?> <?= $f['type']==='number'?'step="1"':'' ?> placeholder="Enter <?= e(strtolower($f['label'])) ?>" <?= $f['type']==='email'?'autocomplete="email"':'' ?>><?php } ?><?php if(!empty($f['hint'])): ?><small class="hint"><?= e($f['hint']) ?></small><?php endif; ?></div><?php endforeach; ?></div><button class="btn" type="submit">Save record</button> <a class="btn secondary" href="records.php?entity=<?= e($key) ?>">Cancel</a></form></div>
<?php else: $q=trim($_GET['q']??'');$limit=200;$sqlq="SELECT * FROM `$table`";$params=[];$types='';if($q!==''){$parts=[];foreach(array_keys($fields) as $col){$parts[]="CAST(`$col` AS CHAR) LIKE ?";$params[]='%'.$q.'%';$types.='s';}if($parts){$sqlq.=' WHERE '.implode(' OR ',$parts);}}$sqlq.=" ORDER BY `$pk` DESC LIMIT $limit";if($params){$stmt=$conn->prepare($sqlq);$stmt->bind_param($types,...$params);$stmt->execute();$rows=$stmt->get_result();}else{$rows=$conn->query($sqlq);} ?>
<div class="card"><div class="toolbar"><form class="searchbar" method="get"><input type="hidden" name="entity" value="<?= e($key) ?>"><input type="search" name="q" value="<?= e($q) ?>" placeholder="Search records…"><button class="btn" type="submit">Search</button><?php if($q!==''): ?><a class="btn secondary" href="records.php?entity=<?= e($key) ?>">Clear</a><?php endif; ?></form><a class="btn" href="records.php?entity=<?= e($key) ?>&action=create">＋ Add record</a></div><div class="table-wrap"><table><thead><tr><th><?= e(str_replace('_',' ', $pk)) ?></th><?php foreach($fields as $col=>$f): if($col===$pk)continue; ?><th><?= e($f['label']) ?></th><?php endforeach; ?><th>Actions</th></tr></thead><tbody><?php $count=0;while($row=$rows->fetch_assoc()):$count++; ?><tr><td><?= e($row[$pk]) ?></td><?php foreach($fields as $col=>$f):if($col===$pk)continue; ?><td><?= e($row[$col]??'—') ?></td><?php endforeach; ?><td><div class="actions"><a class="btn secondary small" href="records.php?entity=<?= e($key) ?>&action=edit&id=<?= (int)$row[$pk] ?>">Edit</a><form class="inline-form" method="post" action="records.php?entity=<?= e($key) ?>&action=delete&id=<?= (int)$row[$pk] ?>" onsubmit="return confirm('Delete this record? This cannot be undone.');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn danger small" type="submit">Delete</button></form></div></td></tr><?php endwhile; if(!$count): ?><tr><td colspan="<?= count($fields)+1 ?>" class="empty">No records found. Add a record or change your search.</td></tr><?php endif; ?></tbody></table></div><p class="hint">Showing up to 200 records. Search matches any field. Use Edit to update a record.</p></div><?php endif; ?>
<?php require 'includes/footer.php'; ?>